function IdolLive3D_RoleColliderMgr:__init( mainForRuntime_, roleTF_ )

    self.mainForRuntime = mainForRuntime_
    self.roleTF = roleTF_

    self.baseColliders = {} -- map k:idStr, v:collider

    local allRoleColliders = IdolLive3D_Utils.FindAllRoleColliders( self.roleTF, true ) -- includeInactive
    for idStr,collider in pairs(allRoleColliders) do 
        local idComp =  KTool.GetComponent(collider.gameObject, typeof(IDComp))
        if idComp.id == IdolLive3D_StatesV2.ColliderIdType.Base then 
            self.baseColliders[string.lower(idStr)] = collider
        end 
    end 
end



