-- 进入新的 stage 或者 supertimeline 时:
function IdolLive3D_RoleColliderMgr:IntoNewState( allConditionKeys_ ) 
    local isHaveAllKey = (allConditionKeys_["_all_"] == 1)
    local isHaveAnyKey = (allConditionKeys_["_any_"] == 1)
    if isHaveAllKey or isHaveAnyKey then 
        -- 把所有 role collider 开启:
        for _,collider in pairs(self.baseColliders) do 
            collider.enabled = true
        end
        print("== 发现 key: _any_ 或 _all_; 开启所有 role collider;")
        return
    end

    ---
    print("== 开启 collider: --------------------")
    -- 先把所有 role collider 关闭:
    for _,collider in pairs(self.baseColliders) do 
        collider.enabled = false
    end
    -- 打开需要的 colliders: 
    for key,val in pairs(allConditionKeys_) do 
        if val == 1 then
            local collider = self.baseColliders[key]
            if isNotNull(collider) then 
                collider.enabled = true
                print("-- 开启 collider: k:" ..tostring(key)..", go:"..tostring(collider.name))
            else 
                if string.startsWith(key, "ui_") then 
                    -- 虚拟按钮, 不用管
                elseif key == "success" or key == "fail" then
                    -- 对抗判断, 不用管
                else 
                    printError("异常, baseColliders 中 "..tostring(key).." 为空")
                end 
            end 
        end
    end 
end




return IdolLive3D_RoleColliderMgr
